// Intelligence: forecasts, customer intelligence, recommendations, routing, insights, assistant.
// Owner: Agent E1 (see docs/architecture/MODULE_CONTRACTS.md). Other agents
// import from here but do not edit this file.
import { z } from 'zod';
import { locale, optionalText, text, uuid } from './common';

export const intelligenceContractsVersion = 2 as const;

const int = (min: number, max: number, def: number) => z.coerce.number().int().min(min).max(max).default(def);

// ---------------------------------------------------------------------------
// Inputs
// ---------------------------------------------------------------------------
export const forecastQuery = z.object({
  branchId: uuid,
  productId: uuid.optional(),
  horizon: int(7, 14, 14),
  top: int(1, 10, 5),
  historyDays: int(28, 730, 365),
});
export type ForecastQuery = z.infer<typeof forecastQuery>;

export const SEGMENT_KEYS = ['new', 'champions', 'loyal', 'potential_loyal', 'promising', 'needs_attention', 'at_risk', 'hibernating'] as const;
export const segmentKey = z.enum(SEGMENT_KEYS);
export type SegmentKey = (typeof SEGMENT_KEYS)[number];

export const segmentMembersQuery = z.object({
  limit: int(1, 200, 50),
  cursor: z.coerce.number().int().min(0).max(1_000_000).optional(),
});

export const churnQuery = z.object({
  limit: int(1, 200, 50),
  windowDays: int(30, 180, 60),
});

export const recommendationsQuery = z.object({
  branchId: uuid,
  productId: uuid.optional(),
  customerId: uuid.optional(),
  k: int(1, 10, 5),
});

export const routePlanInput = z.object({
  branchId: uuid,
  driverId: uuid,
  objective: z.enum(['distance', 'lateness']).default('distance'),
  speedKmh: z.number().min(5).max(80).default(25),
  promiseMinutes: z.number().int().min(10).max(180).default(45),
});
export type RoutePlanInput = z.infer<typeof routePlanInput>;

export const INSIGHT_STATUSES = ['new', 'seen', 'dismissed', 'acted'] as const;
export const insightsQuery = z.object({
  status: z.enum(INSIGHT_STATUSES).optional(),
  branchId: uuid.optional(),
  limit: int(1, 200, 50),
  cursor: z.string().max(200).optional(),
});
export const insightStatusInput = z.object({ status: z.enum(['seen', 'dismissed', 'acted']) });

export const assistantMessageInput = z.object({
  threadId: uuid.optional(),
  message: text(1000),
  locale: locale.default('en'),
  branchId: uuid.optional(),
});
export type AssistantMessageInput = z.infer<typeof assistantMessageInput>;

export const COPY_KINDS = ['caption', 'menu_description', 'campaign'] as const;
export const COPY_CHANNELS = ['instagram', 'facebook', 'tiktok', 'whatsapp', 'sms', 'website'] as const;
export const generateCopyInput = z.object({
  kind: z.enum(COPY_KINDS),
  locale: z.enum(['en', 'ar']),
  productId: uuid.optional(),
  subject: z.object({
    name: text(120),
    nameAr: optionalText(120),
    description: optionalText(500),
  }).optional(),
  tone: z.enum(['friendly', 'premium', 'playful']).default('friendly'),
  channel: z.enum(COPY_CHANNELS).default('instagram'),
  offer: optionalText(120),
}).refine((v) => v.productId || v.subject, { message: 'productId or subject is required', path: ['productId'] });
export type GenerateCopyInput = z.infer<typeof generateCopyInput>;

// ---------------------------------------------------------------------------
// Responses (camelCase JSON)
// ---------------------------------------------------------------------------
export type ForecastModelName = 'seasonal_naive_7' | 'moving_average_28' | 'hist_gbm';
export interface ForecastMetrics { mae: number; rmse: number; wape: number | null; n: number }
export interface ForecastPoint { date: string; yhat: number; lower: number; upper: number; isWeekend: boolean; isRamadan: boolean }
export interface ItemForecast {
  productId: string; name: string; nameAr: string | null;
  model: ForecastModelName; selection: string; fallbackReason: string | null;
  candidates: Array<{ model: ForecastModelName; metrics: ForecastMetrics | null; excluded: string | null }>;
  backtest: { folds: number; horizon: number; origins: string[] };
  interval: { level: number; method: string };
  forecast: ForecastPoint[];
  history: Array<{ date: string; quantity: number }>;
  coverage: { start: string; end: string; days: number; nonZeroDays: number; totalQuantity: number };
}
export interface ForecastResponse {
  branchId: string; horizon: number; asOf: string; generatedAt: string;
  calendar: { weekendDays: string[]; ramadan: Array<{ start: string; end: string }>; ramadanSource: string };
  items: ItemForecast[]; isSyntheticData: false; computationMs: number;
}

export interface SegmentsResponse {
  asOf: string; method: 'rfm_quintiles'; totalCustomers: number; predictionId: string;
  segments: Array<{ key: SegmentKey; count: number }>;
}
export interface SegmentMember {
  customerId: string; displayName: string | null; segment: SegmentKey; r: number; f: number; m: number;
  recencyDays: number; frequency: number; monetaryMinor: number;
}

export interface ChurnResponse {
  method: 'logistic_regression' | 'heuristic'; isHeuristic: boolean; reason: string | null; windowDays: number;
  labelCohort: { cutoff: string; customers: number; churned: number; retained: number };
  evaluation: Record<string, unknown> | null; currency: string;
  customers: Array<{ customerId: string; displayName: string | null; risk: number; band: 'high' | 'medium' | 'low';
    recencyDays: number; frequency: number; monetaryMinor: number }>;
}

export interface RecommendedItem {
  productId: string; name: string; nameAr: string | null; source: 'association' | 'popularity' | 'hybrid';
  confidence?: number; lift?: number | null; support?: number; pairCount?: number; score?: number;
}
export interface RecommendationsResponse {
  branchId: string; method: string; weights: Record<string, number>;
  items: Array<{ productId: string; name: string; nameAr: string | null; frequentlyBoughtWith: RecommendedItem[] }>;
  customer: { customerId: string; nextItems: RecommendedItem[] } | null;
  popular: RecommendedItem[]; stats: { baskets: number; distinctItems: number; pairs: number };
}

export interface RoutePlanResponse {
  predictionId: string; driverId: string; branchId: string; method: string; objective: 'distance' | 'lateness';
  start: { lat: number; lng: number; source: 'branch' | 'driver_location' };
  stops: Array<{ jobId: string; orderId: string; orderNumber: string; sequence: number; naiveSequence: number; lat: number; lng: number;
    address: string | null; promisedAt: string | null; arrivesAt: string | null; lateMinutes: number }>;
  skipped: Array<{ jobId: string; reason: 'missing_coordinates' }>;
  distanceKm: number; durationMinutes: number; violations: Array<{ jobId: string; lateMinutes: number }>;
  naive: { distanceKm: number; durationMinutes: number; violations: number };
  distanceSavingPct: number; computationMs: number;
  distanceModel: { kind: 'haversine'; roadFactor: number; speedKmh: number };
}

export interface Insight {
  id: string; branchId: string | null; kind: string; severity: 'info' | 'opportunity' | 'warning' | 'critical';
  title: string; body: string; evidence: Record<string, unknown>; method: 'deterministic' | 'model' | 'llm';
  status: (typeof INSIGHT_STATUSES)[number]; createdAt: string;
}

export interface AssistantToolCall { name: string; args: Record<string, unknown>; result?: unknown; error?: string }
export interface AssistantReply {
  threadId: string; messageId: string; mode: 'rules' | 'gemini'; answer: string; grounded: boolean;
  toolCalls: AssistantToolCall[]; citations: string[];
}

export interface GeneratedCopy {
  kind: (typeof COPY_KINDS)[number]; locale: 'en' | 'ar'; text: string; provider: 'gemini' | 'template'; isFallback: boolean;
}

export interface ResearchModel {
  id: string; task: string; name: string; version: string; algorithm: string; params: Record<string, unknown>;
  dataset: Record<string, unknown>; isSyntheticData: boolean;
  evaluations: Array<{ runId: string; split: string; metrics: Record<string, unknown>; baselineMetrics: Record<string, unknown> | null;
    isSyntheticData: boolean; notes: string | null; createdAt: string }>;
}
